#define PAYLOAD_MASK UINT64_C(0x000000ffffffffff)
#define FLOAT_OFFSET UINT64_C(0x0001000000000000)
#define POSITIVE_NAN_COUNT UINT64_C(0x000fffffffffffff)

static _Atomic uint64_t next_layout_token=1;
typedef struct { uint64_t bits; uint8_t tag; } scalar_box;
typedef struct { uint32_t length; char bytes[]; } string_box;
typedef struct { uint64_t address, length, owner; } managed_box;
typedef struct { uint32_t size, owner_count; unsigned char storage[]; } aggregate_box;
typedef struct { uint32_t function, signature; uint64_t captures; } callable_box;
typedef struct { uint8_t kind, negative; uint16_t reserved; uint32_t length; uint64_t magnitude; const char *bytes; } word_key;
typedef struct { uint64_t key, value, hash; uint32_t argument; uint8_t method; uint8_t reserved[3]; } word_entry;
typedef struct { uint32_t count, capacity, index_capacity, reserved; unsigned char storage[]; } word_map;
typedef struct { uint64_t map, terminal, layout_token; uint32_t remaining; uint8_t frozen, readonly; uint16_t reserved; } word_box;
enum { ABC_OBJECT_WORD_MAP=64, ABC_OBJECT_MANAGED=65, ABC_OBJECT_STORAGE=66 };

static uint64_t immediate(unsigned tag,uint64_t payload){return IMM_PREFIX|((uint64_t)tag<<TAG_SHIFT)|(payload&PAYLOAD_MASK);}
static int float_nan_bits(uint64_t bits){return (bits&UINT64_C(0x7ff0000000000000))==UINT64_C(0x7ff0000000000000)&&(bits&UINT64_C(0x000fffffffffffff));}
static uint64_t encode_float(uint64_t bits){uint64_t rank;if(float_nan_bits(bits))rank=UINT64_MAX-2*POSITIVE_NAN_COUNT+1;else rank=bits<UINT64_C(0x8000000000000000)?bits:bits-POSITIVE_NAN_COUNT;return rank+FLOAT_OFFSET;}
