static void trace_value(abc_vm *v,uint64_t *value,void (*trace)(struct gc_edge,struct gc_heap *,void *),struct gc_heap *heap,void *data){(void)v;uint64_t x=*value;if(x&&!(x&15)&&!(x>>48))trace(gc_edge(value),heap,data);}
static word_entry *map_entries(word_map *map){return (word_entry *)map->storage;}
static uint32_t *map_index(word_map *map){return (uint32_t *)(void *)(map_entries(map)+map->capacity);}
static void trace_heap_cell(uint64_t *cell,void (*trace)(struct gc_edge,struct gc_heap *,void *),struct gc_heap *heap,void *data){uint64_t x=*cell;if(x&&!(x&15)&&!(x>>48))trace(gc_edge(cell),heap,data);}
