static unsigned primitive_tag(unsigned p){static const uint8_t tags[]={ABC_ANY_UNIT,ABC_ANY_BOOL,ABC_ANY_U8,ABC_ANY_U16,ABC_ANY_U32,ABC_ANY_U64,ABC_ANY_I32,ABC_ANY_I64,ABC_ANY_F64,ABC_ANY_STRING,255,ABC_ANY_WORD};return p<sizeof tags?tags[p]:255;}
